from .base import UePcServerRunner
from robot.api import logger


class PingDataTransfer(UePcServerRunner):
    """Ping Data Transfer"""
    def __init__(self, ue_name, dt_name, ue_pc_instance, ue_id, ue_ip, ue_type, command_tail,
                 dt_protocol="PING",
                 dt_direction="UL", app_srv_lte_ip=None, analyzer_params=None, verification_delay=1,
                 local_timestamp=None):
        """
        :param ue_name:
        :param dt_name:
        :param ue_pc_instance:
        :param ue_id:
        :param ue_ip:
        :param ue_type:
        :param command_tail:
        :param dt_protocol:
        :param dt_direction:
        :param app_srv_lte_ip:
        :param analyzer_params:
        :param verification_delay:
        :param local_timestamp:
        """
        super(PingDataTransfer, self).__init__(ue_name=ue_name,
                                               dt_name=dt_name,
                                               dt_protocol=dt_protocol,
                                               dt_direction=dt_direction,
                                               ue_pc_instance=ue_pc_instance,
                                               ue_id=ue_id,
                                               ue_ip=ue_ip,
                                               ue_type=ue_type,
                                               command_tail=command_tail,
                                               app_srv_lte_ip=app_srv_lte_ip,
                                               analyzer_params=analyzer_params,
                                               verification_delay=verification_delay,
                                               local_timestamp=local_timestamp)
        logger.info("Initialized object {} on UE PC.".format(self.__class__.__name__))

    def get_statistics(self):
        """
        Returns dictionary with ping stats

        :return: dict
        :raises ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.py DataTransferUePcServerException if get statistics failed
        """
        data = super(PingDataTransfer, self).get_statistics()
        statistics = dict()
        statistics['max_latency'] = data.get('max', None)
        statistics['min_latency'] = data.get('min', None)
        statistics['avg_latency'] = data.get('avg', None)
        statistics['packet_loss'] = data.get('packet_loss', None)
        statistics['drop'] = data.get('drop', None)
        return statistics
